#!/usr/bin/env node

// src/cli.ts
import { resolve } from "node:path";

// src/core.ts
import { existsSync as existsSync3, mkdirSync, readdirSync as readdirSync2, readFileSync as readFileSync3, rmSync, writeFileSync } from "node:fs";
import { dirname, join as join3 } from "node:path";

// src/adapters.ts
import { existsSync as existsSync2, readFileSync as readFileSync2 } from "node:fs";
import { join as join2 } from "node:path";

// src/source.ts
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
var SOURCE_DIR = ".skillcast";
var MARKER = "generated by skillcast from";

class SourceError extends Error {
}
function normalize(text) {
  return text.replace(/\r\n?/g, `
`).replace(/\s+$/, "") + `
`;
}
function parseFrontmatter(text, file) {
  const t = text.replace(/\r\n?/g, `
`);
  if (!t.startsWith(`---
`))
    return null;
  const end = t.indexOf(`
---`, 4);
  if (end < 0)
    throw new SourceError(`${file}: frontmatter is not closed with ---`);
  const fields = new Map;
  for (const [i, line] of t.slice(4, end).split(`
`).entries()) {
    if (!line.trim())
      continue;
    const m = /^([A-Za-z][\w-]*):\s*(.*)$/.exec(line);
    if (!m)
      throw new SourceError(`${file}:${i + 2}: expected "key: value" in frontmatter, got "${line}"`);
    fields.set(m[1], m[2].trim());
  }
  return { fields, body: t.slice(end + 4).replace(/^\n+/, "") };
}
function unquote(raw) {
  if (raw.startsWith('"')) {
    try {
      return JSON.parse(raw);
    } catch {
      throw new SourceError(`invalid quoted value ${raw}`);
    }
  }
  if (raw.startsWith("'") && raw.endsWith("'"))
    return raw.slice(1, -1).replace(/''/g, "'");
  return raw;
}
var OPEN = /^<!--\s*only:([\w-]+)\s*-->\s*$/;
var CLOSE = /^<!--\s*\/only\s*-->\s*$/;
function selectBlocks(body, harness, known, file) {
  const out = [];
  let current = null;
  let openedAt = 0;
  for (const [i, line] of body.split(`
`).entries()) {
    const open = OPEN.exec(line);
    if (open) {
      if (current)
        throw new SourceError(`${file}:${i + 1}: nested only-block inside only:${current}`);
      if (!known.includes(open[1]))
        throw new SourceError(`${file}:${i + 1}: unknown harness "${open[1]}" (known: ${known.join(", ")})`);
      current = open[1];
      openedAt = i + 1;
      continue;
    }
    if (CLOSE.test(line)) {
      if (!current)
        throw new SourceError(`${file}:${i + 1}: <!-- /only --> without an opening block`);
      current = null;
      continue;
    }
    if (!current || current === harness)
      out.push(line);
  }
  if (current)
    throw new SourceError(`${file}:${openedAt}: only:${current} block is never closed`);
  return normalize(out.join(`
`).replace(/\n{3,}/g, `

`));
}
var NAME = /^[a-z0-9][a-z0-9-]*$/;
function loadSource(root) {
  const dir = join(root, SOURCE_DIR);
  if (!existsSync(dir))
    throw new SourceError(`${SOURCE_DIR}/ not found; run "skillcast init" first`);
  const source = { skills: [] };
  const rulesPath = join(dir, "rules.md");
  if (existsSync(rulesPath))
    source.rules = { body: normalize(readFileSync(rulesPath, "utf8")), file: `${SOURCE_DIR}/rules.md` };
  const skillsDir = join(dir, "skills");
  const files = existsSync(skillsDir) ? readdirSync(skillsDir).filter((f) => f.endsWith(".md")).sort() : [];
  const seen = new Map;
  for (const f of files) {
    const file = `${SOURCE_DIR}/skills/${f}`;
    const fm = parseFrontmatter(readFileSync(join(skillsDir, f), "utf8"), file);
    if (!fm)
      throw new SourceError(`${file}: missing frontmatter (needs name and description)`);
    const name = fm.fields.get("name") && unquote(fm.fields.get("name"));
    const description = fm.fields.get("description") && unquote(fm.fields.get("description"));
    if (!name)
      throw new SourceError(`${file}: frontmatter field "name" is missing`);
    if (!description)
      throw new SourceError(`${file}: frontmatter field "description" is missing`);
    if (!NAME.test(name))
      throw new SourceError(`${file}: name "${name}" must be lowercase letters, digits and dashes`);
    if (seen.has(name))
      throw new SourceError(`${file}: duplicate skill name "${name}" (also in ${seen.get(name)})`);
    if (`${name}.md` !== f)
      throw new SourceError(`${file}: name "${name}" must match the file name (${name}.md)`);
    seen.set(name, file);
    const extra = new Map([...fm.fields].filter(([k]) => k !== "name" && k !== "description"));
    source.skills.push({ name, description, extra, body: normalize(fm.body), file });
  }
  return source;
}

// src/adapters.ts
var marker = (file) => `<!-- ${MARKER} ${file}. Edit the source, then run: skillcast build -->`;
var q = (s) => JSON.stringify(s);
function skillMd(skill, body, mark) {
  const extra = [...skill.extra].filter(([k]) => !k.startsWith("cursor-")).map(([k, v]) => `${k}: ${v}`);
  return ["---", `name: ${skill.name}`, `description: ${q(skill.description)}`, ...extra, "---", mark, "", body].join(`
`);
}
var FORMATS = ["skill-md", "mdc", "plain"];
var RENDER = {
  "skill-md": skillMd,
  mdc: (skill, body, mark) => [
    "---",
    `description: ${q(skill.description)}`,
    `globs: ${skill.extra.get("cursor-globs") ?? ""}`.trimEnd(),
    `alwaysApply: ${skill.extra.get("cursor-alwaysApply") ?? "false"}`,
    "---",
    mark,
    "",
    body
  ].join(`
`),
  plain: (skill, body, mark) => [mark, "", `# ${skill.name}`, "", skill.description, "", body].join(`
`)
};

class ConfigError extends Error {
}
function fromSpec(spec, where = "harness") {
  const parts = spec.skills.split("{name}");
  if (parts.length !== 2)
    throw new ConfigError(`${where} "${spec.id}": skills path must contain {name} exactly once`);
  if (!FORMATS.includes(spec.format))
    throw new ConfigError(`${where} "${spec.id}": unknown format "${spec.format}" (use ${FORMATS.join(", ")})`);
  const unsafe = (p) => p.startsWith("/") || /^[A-Za-z]:/.test(p) || p.split(/[\\/]/).includes("..");
  if (spec.rules !== undefined && (typeof spec.rules !== "string" || !spec.rules || unsafe(spec.rules))) {
    throw new ConfigError(`${where} "${spec.id}": rules must be a relative path inside the repo`);
  }
  const [before, after] = parts;
  if (!before.endsWith("/") || unsafe(spec.skills))
    throw new ConfigError(`${where} "${spec.id}": skills path must be relative and put {name} after a "/"`);
  const dir = before.slice(0, -1);
  let glob;
  if (after.startsWith("/") && after.split("/").length === 2 && after.length > 1)
    glob = { dir, file: after.slice(1), suffix: "" };
  else if (after.startsWith(".") && !after.includes("/"))
    glob = { dir, file: null, suffix: after };
  else
    throw new ConfigError(`${where} "${spec.id}": skills path must end in {name}/<file> or {name}.<ext>`);
  return {
    id: spec.id,
    rules: spec.rules ? { path: spec.rules } : undefined,
    skillPath: (n) => `${before}${n}${after}`,
    skillGlob: glob,
    renderSkill: RENDER[spec.format]
  };
}
var BUILT_IN = [
  { id: "claude", rules: "CLAUDE.md", skills: ".claude/skills/{name}/SKILL.md", format: "skill-md" },
  { id: "codex", rules: "AGENTS.md", skills: ".agents/skills/{name}/SKILL.md", format: "skill-md" },
  { id: "cursor", skills: ".cursor/rules/{name}.mdc", format: "mdc" }
];
var [claude, codex, cursor] = BUILT_IN.map((h) => fromSpec(h));
var DEFAULT_ADAPTERS = [claude, codex, cursor];
function adaptersFor(root) {
  const path = join2(root, SOURCE_DIR, "config.json");
  if (!existsSync2(path))
    return DEFAULT_ADAPTERS;
  const where = `${SOURCE_DIR}/config.json`;
  let config;
  try {
    config = JSON.parse(readFileSync2(path, "utf8"));
  } catch (e) {
    throw new ConfigError(`${where}: invalid JSON (${e.message})`);
  }
  if (!Array.isArray(config.harnesses) || config.harnesses.length === 0)
    throw new ConfigError(`${where}: "harnesses" must be a non-empty list`);
  const adapters = config.harnesses.map((h) => {
    if (typeof h === "string") {
      const spec = BUILT_IN.find((b) => b.id === h);
      if (!spec)
        throw new ConfigError(`${where}: unknown harness "${h}" (built in: ${BUILT_IN.map((b) => b.id).join(", ")}; add others as objects)`);
      return fromSpec(spec);
    }
    const spec = h;
    if (!spec || typeof spec.id !== "string" || !/^[a-z0-9][a-z0-9-]*$/.test(spec.id) || typeof spec.skills !== "string") {
      throw new ConfigError(`${where}: each custom harness needs "id" (lowercase) and "skills"`);
    }
    return fromSpec(spec, where);
  });
  const seen = new Set;
  for (const a of adapters) {
    for (const key of [`id ${a.id}`, a.rules && `path ${a.rules.path}`, `path ${a.skillPath("x")}`]) {
      if (!key)
        continue;
      if (seen.has(key))
        throw new ConfigError(`${where}: duplicate ${key}`);
      seen.add(key);
    }
  }
  return adapters;
}
function plan(source, adapters = DEFAULT_ADAPTERS) {
  const ids = [...new Set([...adapters.map((a) => a.id), ...BUILT_IN.map((b) => b.id)])];
  const ruleIds = [...new Set([...adapters.filter((a) => a.rules).map((a) => a.id), ...BUILT_IN.filter((b) => b.rules).map((b) => b.id)])];
  const out = new Map;
  for (const a of adapters) {
    if (a.rules && source.rules) {
      const body = selectBlocks(source.rules.body, a.id, ruleIds, source.rules.file);
      out.set(a.rules.path, `${marker(source.rules.file)}

${body}`);
    }
    for (const s of source.skills)
      out.set(a.skillPath(s.name), a.renderSkill(s, selectBlocks(s.body, a.id, ids, s.file), marker(s.file)));
  }
  return new Map([...out].sort(([x], [y]) => x < y ? -1 : 1));
}

// src/core.ts
var isGenerated = (text) => text.includes(MARKER);
var read = (root, rel) => existsSync3(join3(root, rel)) ? readFileSync3(join3(root, rel), "utf8") : null;
function generatedOnDisk(root, adapters) {
  const found = [];
  const scan = [...adapters, ...DEFAULT_ADAPTERS.filter((d) => !adapters.some((a) => a.id === d.id))];
  for (const a of scan) {
    const { dir, file, suffix } = a.skillGlob;
    if (!existsSync3(join3(root, dir)))
      continue;
    for (const entry of readdirSync2(join3(root, dir)).sort()) {
      const rel = file ? `${dir}/${entry}/${file}` : entry.endsWith(suffix) ? `${dir}/${entry}` : null;
      const text = rel && read(root, rel);
      if (rel && text && isGenerated(text))
        found.push(rel);
    }
    if (a.rules && isGenerated(read(root, a.rules.path) ?? ""))
      found.push(a.rules.path);
  }
  return [...new Set(found)];
}
function firstDifference(expected, actual) {
  const e = expected.split(`
`);
  const a = actual.split(`
`);
  for (let i = 0;i < Math.max(e.length, a.length); i++) {
    if (e[i] !== a[i])
      return `line ${i + 1}: expected ${JSON.stringify(e[i] ?? "<end of file>")}, found ${JSON.stringify(a[i] ?? "<end of file>")}`;
  }
  return "contents differ";
}
function check(root, adapters = adaptersFor(root)) {
  const planned = plan(loadSource(root), adapters);
  const problems = [];
  for (const [file, expected] of planned) {
    const actual = read(root, file);
    if (actual === null)
      problems.push({ file, kind: "missing", detail: "not generated yet" });
    else if (!isGenerated(actual))
      problems.push({ file, kind: "handwritten", detail: "file exists without the generated marker" });
    else if (actual !== expected)
      problems.push({ file, kind: "changed", detail: firstDifference(expected, actual) });
  }
  for (const file of generatedOnDisk(root, adapters)) {
    if (!planned.has(file))
      problems.push({ file, kind: "extra", detail: "generated file has no source any more" });
  }
  return problems;
}
function build(root, adapters = adaptersFor(root), adopt = new Set) {
  const planned = plan(loadSource(root), adapters);
  for (const file of planned.keys()) {
    const actual = read(root, file);
    if (actual !== null && !isGenerated(actual) && !adopt.has(file)) {
      throw new SourceError(`${file} exists and was not generated by skillcast; run "skillcast init" to import it`);
    }
  }
  const changed = [];
  for (const [file, content] of planned) {
    if (read(root, file) === content)
      continue;
    mkdirSync(dirname(join3(root, file)), { recursive: true });
    writeFileSync(join3(root, file), content);
    changed.push(file);
  }
  for (const file of generatedOnDisk(root, adapters)) {
    if (planned.has(file))
      continue;
    rmSync(join3(root, file));
    changed.push(`${file} (removed)`);
  }
  return changed;
}
function init(root, adapters = adaptersFor(root)) {
  if (existsSync3(join3(root, SOURCE_DIR)))
    throw new SourceError(`${SOURCE_DIR}/ already exists`);
  const conflicts = [];
  const imported = [];
  let rules;
  for (const a of adapters) {
    const text = a.rules && read(root, a.rules.path);
    if (!a.rules || !text || isGenerated(text))
      continue;
    const body = normalize(text);
    if (rules && rules.body !== body)
      conflicts.push(`${rules.from} and ${a.rules.path} differ; make them equal or delete one, then run init again`);
    rules ??= { body, from: a.rules.path };
    imported.push(a.rules.path);
  }
  const skills = new Map;
  for (const a of adapters.filter((x) => x.skillGlob.file)) {
    const dir = a.skillGlob.dir;
    if (!existsSync3(join3(root, dir)))
      continue;
    for (const name of readdirSync2(join3(root, dir)).sort()) {
      const from = `${dir}/${name}/${a.skillGlob.file}`;
      const text = read(root, from);
      if (!text || isGenerated(text))
        continue;
      const fm = parseFrontmatter(text, from);
      if (!fm?.fields.get("description")) {
        conflicts.push(`${from}: no frontmatter description, cannot import`);
        continue;
      }
      const extra = new Map([...fm.fields].filter(([k]) => k !== "name" && k !== "description"));
      const skill = { description: unquote(fm.fields.get("description")), extra, body: normalize(fm.body), from };
      const prev = skills.get(name);
      if (prev && (prev.description !== skill.description || prev.body !== skill.body)) {
        conflicts.push(`${prev.from} and ${from} describe skill "${name}" differently`);
      } else if (prev) {
        for (const [k, v] of extra)
          prev.extra.set(k, v);
      } else
        skills.set(name, skill);
      imported.push(from);
    }
  }
  if (conflicts.length)
    throw new SourceError(`init stopped, nothing was written:
- ${conflicts.join(`
- `)}`);
  mkdirSync(join3(root, SOURCE_DIR, "skills"), { recursive: true });
  if (rules)
    writeFileSync(join3(root, SOURCE_DIR, "rules.md"), rules.body);
  for (const [name, s] of skills) {
    const extra = [...s.extra].map(([k, v]) => `${k}: ${v}`);
    const head = ["---", `name: ${name}`, `description: ${JSON.stringify(s.description)}`, ...extra, "---", ""].join(`
`);
    writeFileSync(join3(root, SOURCE_DIR, "skills", `${name}.md`), `${head}${s.body}`);
  }
  try {
    return { imported, built: build(root, adapters, new Set(imported)) };
  } catch (e) {
    rmSync(join3(root, SOURCE_DIR), { recursive: true, force: true });
    if (e instanceof SourceError)
      throw new SourceError(`init stopped, nothing was written:
- ${e.message}`);
    throw e;
  }
}

// src/cli.ts
var USAGE = `skillcast: write agent skills once, project them to Claude Code, Codex and Cursor.

Usage:
  skillcast init   [--root <dir>]   import existing CLAUDE.md, AGENTS.md and skills into .skillcast/
  skillcast build  [--root <dir>]   write every harness file from .skillcast/
  skillcast check  [--root <dir>]   exit 1 if a generated file is missing, edited by hand or stale

Exit codes: 0 ok, 1 drift found, 2 usage or source error.`;
function main(argv) {
  const [command, ...rest] = argv;
  const rootFlag = rest.indexOf("--root");
  const root = resolve(rootFlag >= 0 ? rest[rootFlag + 1] ?? "." : ".");
  try {
    if (command === "build") {
      const changed = build(root);
      console.log(changed.length ? changed.map((f) => `wrote ${f}`).join(`
`) : "up to date");
      return 0;
    }
    if (command === "check") {
      const problems = check(root);
      for (const p of problems)
        console.error(`${p.kind.padEnd(11)} ${p.file}: ${p.detail}`);
      if (problems.length)
        console.error(`
${problems.length} problem(s). Fix the source in .skillcast/ and run: skillcast build`);
      else
        console.log("all projections match the source");
      return problems.length ? 1 : 0;
    }
    if (command === "init") {
      const { imported, built } = init(root);
      console.log([...imported.map((f) => `imported ${f}`), ...built.map((f) => `wrote ${f}`)].join(`
`) || "created empty .skillcast/");
      return 0;
    }
    console.log(USAGE);
    return command === undefined || command === "--help" || command === "-h" ? 0 : 2;
  } catch (e) {
    if (e instanceof SourceError || e instanceof ConfigError) {
      console.error(`skillcast: ${e.message}`);
      return 2;
    }
    throw e;
  }
}

// src/bin.ts
process.exit(main(process.argv.slice(2)));
